98	    /**
99	     * Normalise a raw telephone number to E.164 form.
100	     *
101	     * <p>Spaces, dashes and brackets are stripped. A leading '+' and its country
102	     * code are kept when present; otherwise country code '+61' is assumed and a
103	     * single leading '0' is dropped from the national digits. The result must have
104	     * between 8 and 15 digits after the '+'.
105	     *
106	     * <p>When the caller supplies the country code explicitly (a leading '+'), the
107	     * national-number length is additionally validated against that country code:
108	     * '+61' requires 9 national digits and '+1' requires 10. A number whose national
109	     * length is wrong for its country is rejected.
110	     *
111	     * @return the E.164 string, or {@code null} if the input cannot form a valid one.
112	     */
113	    static String toE164(String raw) {
114	        if (raw == null) {
115	            return null;
116	        }
117	        String cleaned = raw.replaceAll("[\\s()\\[\\]-]", "");
118	        String digits;
119	        boolean explicitCountryCode;
120	        if (cleaned.startsWith("+")) {
121	            digits = cleaned.substring(1);
122	            explicitCountryCode = true;
123	        } else {
124	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
125	            digits = "61" + national;
126	            explicitCountryCode = false;
127	        }
128	        if (!digits.matches("[0-9]{8,15}")) {
129	            return null;
130	        }
131	        if (explicitCountryCode && !hasValidNationalLength(digits)) {
132	            return null;
133	        }
134	        return "+" + digits;
135	    }
136	
137	    /**
138	     * Validate the national-number length of an E.164 number (its digits without the
139	     * leading '+') against the requirement for its country code: country code '+61'
140	     * (Australia) requires 9 national digits and '+1' (NANP) requires 10. Country codes
141	     * without a configured length requirement are accepted unchanged.
142	     */
143	    private static boolean hasValidNationalLength(String digits) {
144	        if (digits.startsWith("61")) {
145	            return digits.length() - "61".length() == 9;
146	        }
147	        if (digits.startsWith("1")) {
148	            return digits.length() - "1".length() == 10;
149	        }
150	        return true;
151	    }
