153	    /**
154	     * Normalise a text field for case-insensitive, whitespace-insensitive identity
155	     * comparison: leading/trailing whitespace is trimmed, internal runs of whitespace
156	     * are collapsed to a single space, and the result is lower-cased. A {@code null}
157	     * input normalises to the empty string.
158	     */
159	    private static String normaliseIdentity(String value) {
160	        if (value == null) {
161	            return "";
162	        }
163	        return value.trim().replaceAll("\\s+", " ").toLowerCase();
164	    }
165	
166	    /**
167	     * Normalise a postal address into its canonical stored form: leading/trailing whitespace is
168	     * trimmed, internal runs of whitespace are collapsed to a single space, the text is upper-cased,
169	     * and common street-type abbreviations are expanded ({@code ST -> STREET}, {@code RD -> ROAD},
170	     * {@code AVE -> AVENUE}). A {@code null} input normalises to the empty string. This is the value
171	     * that is both stored and used for every address comparison.
172	     */
173	    static String normaliseAddress(String value) {
174	        if (value == null) {
175	            return "";
176	        }
177	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase();
178	        if (collapsed.isEmpty()) {
179	            return "";
180	        }
181	        String[] tokens = collapsed.split(" ");
182	        StringBuilder result = new StringBuilder();
183	        for (int i = 0; i < tokens.length; i++) {
184	            if (i > 0) {
185	                result.append(' ');
186	            }
187	            result.append(expandAddressAbbreviation(tokens[i]));
188	        }
189	        return result.toString();
190	    }
191	
192	    /**
193	     * Expand a single upper-cased address token if it is a known street-type abbreviation, ignoring a
194	     * trailing period (so both {@code ST} and {@code ST.} become {@code STREET}). Unknown tokens are
195	     * returned unchanged.
196	     */
197	    private static String expandAddressAbbreviation(String token) {
198	        String core = token.endsWith(".") ? token.substring(0, token.length() - 1) : token;
199	        return switch (core) {
200	            case "ST" -> "STREET";
201	            case "RD" -> "ROAD";
202	            case "AVE" -> "AVENUE";
203	            default -> token;
204	        };
205	    }
