207	    /**
208	     * Derive the stable, shared household identifier for owners in the same household: the first 12
209	     * lower-case hex characters of the SHA-256 digest over {@code '<normalizedLastName>|<postcode>'},
210	     * so every owner with the same last name and postcode resolves to the same value regardless of
211	     * the order in which they were created.
212	     */
213	    private static String householdId(String lastNameKey, String postcode) {
214	        return hashHex(lastNameKey + "|" + (postcode == null ? "" : postcode), 12, false);
215	    }
216	
217	    /**
218	     * Count how many owners belong to the given owner's household (owners sharing its normalized last
219	     * name and postcode). An owner without a postcode has no household peers and counts as a household
220	     * of one.
221	     */
222	    private int householdSize(Owner owner) {
223	        if (owner.getPostcode() == null) {
224	            return 1;
225	        }
226	        String householdId = householdId(normaliseIdentity(owner.getLastName()), owner.getPostcode());
227	        return (int) this.clinicService.findAllOwners().stream()
228	            .filter(existing -> existing.getPostcode() != null
229	                && householdId.equals(
230	                    householdId(normaliseIdentity(existing.getLastName()), existing.getPostcode())))
231	            .count();
232	    }
233	
234	    /**
235	     * Build an owner's derived duplicate-detection identity key as
236	     * {@code '<normalizedTelephone>|<email or empty>|<householdId or empty>'}. Each {@code null}
237	     * component contributes the empty string, and the email is lower-cased so the comparison is
238	     * case-insensitive. Two owners are duplicates only when their whole identity keys are equal.
239	     */
240	    private static String identityKey(String normalizedTelephone, String email, String householdId) {
241	        String telephone = normalizedTelephone == null ? "" : normalizedTelephone;
242	        String emailKey = email == null ? "" : email.toLowerCase();
243	        String household = householdId == null ? "" : householdId;
244	        return telephone + "|" + emailKey + "|" + household;
245	    }
246	
247	    /**
248	     * Build the customer code for a new owner as {@code '<REGION>-<HASH8>'}, where REGION is the region
249	     * code derived from the postcode (falling back to the city-to-region table, else {@code "UNKNOWN"})
250	     * and HASH8 is the first 8 upper-case hex characters of the SHA-256 digest over
251	     * {@code normalizedTelephone + lastName}. Sequence numbers are no longer used, so the code depends
252	     * only on the owner's own region and identity, not on how many owners already exist.
253	     */
254	    private String nextCustomerCode(String region, String normalizedTelephone, String lastName) {
255	        return region + "-" + hash8(normalizedTelephone + (lastName == null ? "" : lastName));
256	    }
257	
258	    /**
259	     * First 8 upper-case hex characters of the SHA-256 digest of the UTF-8 bytes of {@code input}.
260	     */
261	    private static String hash8(String input) {
262	        return hashHex(input, 8, true);
263	    }
264	
265	    /**
266	     * First {@code length} hex characters of the SHA-256 digest of the UTF-8 bytes of {@code input},
267	     * upper-cased when {@code upperCase} is true and lower-cased otherwise.
268	     */
269	    private static String hashHex(String input, int length, boolean upperCase) {
270	        try {
271	            byte[] digest = MessageDigest.getInstance("SHA-256")
272	                .digest(input.getBytes(StandardCharsets.UTF_8));
273	            StringBuilder sb = new StringBuilder(digest.length * 2);
274	            for (byte b : digest) {
275	                sb.append(String.format("%02x", b));
276	            }
277	            String hex = sb.substring(0, length);
278	            return upperCase ? hex.toUpperCase() : hex;
279	        }
280	        catch (java.security.NoSuchAlgorithmException e) {
281	            throw new IllegalStateException(e);
282	        }
283	    }
