285	    /**
286	     * Resolve an owner's region preferring the postcode: the region is taken from the postcode range
287	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099) when the postcode resolves, otherwise from the
288	     * fixed city-to-region table, else {@code "UNKNOWN"}.
289	     */
290	    private static String region(String postcode, String city) {
291	        String fromPostcode = regionForPostcode(postcode);
292	        return fromPostcode != null ? fromPostcode : regionForCity(city);
293	    }
294	
295	    /**
296	     * Region for a 4-digit postcode by inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099),
297	     * or {@code null} when the postcode is absent, not exactly 4 digits, or in no known range.
298	     */
299	    private static String regionForPostcode(String postcode) {
300	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
301	            return null;
302	        }
303	        int value = Integer.parseInt(postcode);
304	        for (java.util.Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
305	            int[] range = entry.getValue();
306	            if (value >= range[0] && value <= range[1]) {
307	                return entry.getKey();
308	            }
309	        }
310	        return null;
311	    }
312	
313	    /**
314	     * Roll a registration date forward to the next business day: when it falls on a Saturday or
315	     * Sunday it is advanced to the following Monday; weekday dates are returned unchanged.
316	     */
317	    static LocalDate toBusinessDay(LocalDate date) {
318	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
319	            date = date.plusDays(1);
320	        }
321	        return date;
322	    }
323	
324	    /**
325	     * Count the owners already created on the business day that {@code registrationDate} rolls to,
326	     * using the same per-day accumulation path as the daily create-limit rule.
327	     */
328	    private long ownersCreatedOn(LocalDate registrationDate) {
329	        LocalDate day = toBusinessDay(registrationDate);
330	        return this.clinicService.findAllOwners().stream()
331	            .map(Owner::getRegistrationDate)
332	            .filter(existing -> existing != null)
333	            .map(OwnerRestControllerV1::toBusinessDay)
334	            .filter(day::equals)
335	            .count();
336	    }
337	
338	    /**
339	     * Region -> inclusive 4-digit postcode range {@code {low, high}} used to validate a supplied
340	     * postcode against the owner's city region.
341	     */
342	    private static final java.util.Map<String, int[]> REGION_POSTCODES = java.util.Map.of(
343	        "NSW", new int[] {2000, 2099},
344	        "VIC", new int[] {3000, 3099},
345	        "QLD", new int[] {4000, 4099});
346	
347	    /**
348	     * Resolve an owner's region from the city using the fixed city-to-region table
349	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}); {@code "UNKNOWN"}
350	     * when the city is not listed.
351	     */
352	    private static String regionForCity(String city) {
353	        return switch (city == null ? "" : city) {
354	            case "Sydney" -> "NSW";
355	            case "Melbourne" -> "VIC";
356	            case "Brisbane" -> "QLD";
357	            default -> "UNKNOWN";
358	        };
359	    }
360	
361	    /**
362	     * Validate a supplied postcode: it must be exactly 4 digits, and when the owner's city maps to a
363	     * known region the numeric value must fall within that region's inclusive range (NSW 2000-2099,
364	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
365	     */
366	    private static boolean isPostcodeValid(String postcode, String city) {
367	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
368	            return false;
369	        }
370	        int[] range = REGION_POSTCODES.get(regionForCity(city));
371	        if (range == null) {
372	            return true;
373	        }
374	        int value = Integer.parseInt(postcode);
375	        return value >= range[0] && value <= range[1];
376	    }
377	
378	    /**
379	     * Whether the email's domain (the part after the final '@') is on the disposable-domain
380	     * blocklist. A {@code null} email is not disposable; the comparison is case-insensitive.
381	     */
382	    private static boolean isDisposableEmailDomain(String email) {
383	        if (email == null) {
384	            return false;
385	        }
386	        int at = email.lastIndexOf('@');
387	        if (at < 0 || at == email.length() - 1) {
388	            return false;
389	        }
390	        String domain = email.substring(at + 1).toLowerCase();
391	        return DISPOSABLE_EMAIL_DOMAINS.contains(domain);
392	    }
