424	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
425	    @Override
426	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
427	        String telephone = toE164(ownerFieldsDto.getTelephone());
428	        if (telephone == null) {
429	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
430	        }
431	        String email = ownerFieldsDto.getEmail();
432	        if (email != null && !EMAIL_PATTERN.matcher(email).matches()) {
433	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
434	        }
435	        if (isDisposableEmailDomain(email)) {
436	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
437	        }
438	        String address = normaliseAddress(ownerFieldsDto.getAddress());
439	        if (address.isEmpty()) {
440	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
441	        }
442	        String postcode = ownerFieldsDto.getPostcode();
443	        if (postcode != null && !isPostcodeValid(postcode, ownerFieldsDto.getCity())) {
444	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
445	        }
446	        if (ownerFieldsDto.getRegistrationDate() != null
447	            && ownerFieldsDto.getRegistrationDate().isAfter(LocalDate.now())) {
448	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
449	        }
450	        LocalDate effectiveDate = ownerFieldsDto.getRegistrationDate() != null
451	            ? ownerFieldsDto.getRegistrationDate() : LocalDate.now();
452	        LocalDate registrationDate = toBusinessDay(effectiveDate);
453	        long ownersCreatedThatDay = this.clinicService.findAllOwners().stream()
454	            .map(Owner::getRegistrationDate)
455	            .filter(existing -> existing != null)
456	            .map(OwnerRestControllerV1::toBusinessDay)
457	            .filter(registrationDate::equals)
458	            .count();
459	        if (ownersCreatedThatDay >= 100) {
460	            return new ResponseEntity<>(HttpStatus.TOO_MANY_REQUESTS);
461	        }
462	        String cityKey = normaliseIdentity(ownerFieldsDto.getCity());
463	        long ownersInCity = this.clinicService.findAllOwners().stream()
464	            .filter(existing -> normaliseIdentity(existing.getCity()).equals(cityKey))
465	            .count();
466	        if (ownersInCity >= 50) {
467	            return new ResponseEntity<>(HttpStatus.CONFLICT);
468	        }
469	        boolean sharesHousehold = Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
470	        String lastNameKey = normaliseIdentity(ownerFieldsDto.getLastName());
471	        // The household is deterministically keyed on (normalized last name, postcode): every owner
472	        // with a postcode belongs to the household identified by this computed id, and owners sharing
473	        // a last name and postcode share it automatically.
474	        String householdId = (postcode == null) ? null : householdId(lastNameKey, postcode);
475	        // Existing owners already in this household (same last name and postcode).
476	        List<Owner> householdMembers = (householdId == null) ? List.of()
477	            : this.clinicService.findAllOwners().stream()
478	                .filter(existing -> householdId.equals(
479	                    householdId(normaliseIdentity(existing.getLastName()), existing.getPostcode())))
480	                .toList();
481	        // A second owner in an existing household is a household duplicate: rejected with 409 unless
482	        // it declares 'sharesHousehold', which only bypasses this block (the household link itself is
483	        // already assigned deterministically above).
484	        if (!householdMembers.isEmpty() && !sharesHousehold) {
485	            return new ResponseEntity<>(HttpStatus.CONFLICT);
486	        }
487	        String identityKey = identityKey(telephone, email, householdId);
488	        boolean identityInUse = this.clinicService.findAllOwners().stream()
489	            .anyMatch(existing -> identityKey(toE164(existing.getTelephone()),
490	                existing.getEmail(), existing.getHouseholdId()).equals(identityKey));
491	        if (identityInUse) {
492	            return new ResponseEntity<>(HttpStatus.CONFLICT);
493	        }
494	        String firstNameKey = normaliseIdentity(ownerFieldsDto.getFirstName());
495	        int namesakeCount = (int) this.clinicService.findAllOwners().stream()
496	            .filter(existing ->
497	                normaliseIdentity(existing.getFirstName()).equals(firstNameKey)
498	                    && normaliseIdentity(existing.getLastName()).equals(lastNameKey))
499	            .count();
500	        HttpHeaders headers = new HttpHeaders();
501	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
502	        owner.setNamesakeCount(namesakeCount);
503	        owner.setAddress(address);
504	        owner.setTelephone(telephone);
505	        owner.setEmail(email == null ? null : email.toLowerCase());
506	        owner.setRegistrationDate(registrationDate);
507	        owner.setCustomerCode(nextCustomerCode(
508	            region(postcode, owner.getCity()), telephone, owner.getLastName()));
509	        owner.setHouseholdId(householdId);
510	        // A created owner is never flagged as a suspected duplicate: a lone owner has no household
511	        // peer, and a same-household owner can only be created by declaring 'sharesHousehold', which
512	        // makes it an intentional household member rather than a suspected duplicate.
513	        owner.setPossibleDuplicateOf(null);
514	        this.clinicService.saveOwner(owner);
515	        owner.setHouseholdSize(householdSize(owner));
516	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
517	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
518	            ownerMapper.formatMembershipLevel(owner));
519	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
520	        ownerDto.setBulkSignupWarning(ownersCreatedThatDay > 80);
521	        headers.setLocation(UriComponentsBuilder.newInstance()
522	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
523	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
524	    }
