526	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
527	    @Override
528	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
529	        String telephone = toE164(ownerFieldsDto.getTelephone());
530	        if (telephone == null) {
531	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
532	        }
533	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
534	        if (currentOwner == null) {
535	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
536	        }
537	        String email = ownerFieldsDto.getEmail();
538	        if (email != null && !EMAIL_PATTERN.matcher(email).matches()) {
539	            return new ResponseEntity<>(HttpStatus.BAD_REQUEST);
540	        }
541	        currentOwner.setAddress(ownerFieldsDto.getAddress());
542	        currentOwner.setCity(ownerFieldsDto.getCity());
